cd /app && python3 - <<'EOF'
s = open('diff.go').read()
old = '''	// Both sides modified the same path.
	if isModification(a) && isModification(b) {
		return ConflictBothModified
	}

	// Structural changes to the same path (add, replace, move).
	if isStructural(a) || isStructural(b) {
		return ConflictStructural
	}

	return -1
}'''
new = '''	// Both sides modified the same path. Independent text and attribute
	// modifications are not considered conflicts.
	if isModification(a) && isModification(b) {
		if a.Type == b.Type || a.Type == OpReplace || b.Type == OpReplace {
			return ConflictBothModified
		}
		return -1
	}

	// Structural changes to the same path (add, replace, move).
	if isStructural(a) || isStructural(b) {
		return ConflictStructural
	}

	return -1
}'''
if old not in s:
    print("OLD NOT FOUND")
else:
    s = s.replace(old, new)
open('diff.go','w').write(s)
EOF
gofmt -w diff.go && go build ./... && go test ./... 2>&1 | tail -5

